  AND p.generation=(SELECT d.generation FROM session_documents d WHERE d.project_id=a.project_id AND d.session_id=a.session_id AND d.state='live') AND p.prompt_id=a.delivered_prompt_id) OR EXISTS (SELECT 1 FROM session_prompts p WHERE p.project_id=a.project_id AND p.session_id=a.session_id
  AND p.generation=(SELECT d.generation FROM session_documents d WHERE d.project_id=a.project_id AND d.session_id=a.session_id AND d.state='live') AND p.prompt_id=a.prompt_id) THEN 'delivered'
  WHEN a.delivered_prompt_id IS NULL THEN 'unnamed' ELSE 'unavailable' END
      FROM (SELECT project_id,session_id,id FROM prompt_context_answers WHERE project_id=OLD.project_id AND session_id=OLD.session_id) key JOIN prompt_context_answers a ON a.project_id=key.project_id AND a.session_id=key.session_id AND a.id=key.id WHERE a.outcome='served' AND NOT EXISTS (SELECT 1 FROM spore_injections receipt WHERE receipt.project_id=a.project_id AND receipt.session_id=a.session_id AND receipt.id=a.receipt_id) AND NOT EXISTS (SELECT 1 FROM session_tombstones t WHERE t.project_id=a.project_id AND t.session_id=a.session_id) ON CONFLICT(project_id,session_id,kind,record_id) DO UPDATE SET created_at=excluded.created_at,prompt_hint=excluded.prompt_hint,fallback_prompt=excluded.fallback_prompt,state=excluded.state
  WHERE context_placements.state IS NOT excluded.state OR context_placements.prompt_hint IS NOT excluded.prompt_hint OR context_placements.created_at IS NOT excluded.created_at OR context_placements.fallback_prompt IS NOT excluded.fallback_prompt; END;

CREATE TRIGGER IF NOT EXISTS context_placement_row_insert AFTER INSERT ON context_placements BEGIN INSERT INTO context_placement_days(day,state,project_id,n) VALUES(NEW.created_at/86400000,NEW.state,NEW.project_id,+1)
  ON CONFLICT(day,state,project_id) DO UPDATE SET n=n+1; END;

CREATE TRIGGER IF NOT EXISTS context_placement_row_update AFTER UPDATE OF state,created_at ON context_placements WHEN OLD.state IS NOT NEW.state OR OLD.created_at IS NOT NEW.created_at BEGIN INSERT INTO context_placement_days(day,state,project_id,n) VALUES(OLD.created_at/86400000,OLD.state,OLD.project_id,-1)
  ON CONFLICT(day,state,project_id) DO UPDATE SET n=n-1; INSERT INTO context_placement_days(day,state,project_id,n) VALUES(NEW.created_at/86400000,NEW.state,NEW.project_id,+1)
  ON CONFLICT(day,state,project_id) DO UPDATE SET n=n+1; END;

CREATE TRIGGER IF NOT EXISTS context_placement_row_delete AFTER DELETE ON context_placements BEGIN INSERT INTO context_placement_days(day,state,project_id,n) VALUES(OLD.created_at/86400000,OLD.state,OLD.project_id,-1)
  ON CONFLICT(day,state,project_id) DO UPDATE SET n=n-1; END;

INSERT INTO projection_catchup(projection,phase,done) SELECT 'context_placements','contextPlacementReceipts',NOT EXISTS(SELECT 1 FROM spore_injections) ON CONFLICT DO NOTHING;

INSERT INTO projection_catchup(projection,phase,done) SELECT 'context_placements','contextPlacementAnswers',NOT EXISTS(SELECT 1 FROM prompt_context_answers) ON CONFLICT DO NOTHING;

